       end,
       x.correct, x.fact, x.img, x.credit,
       array(select e.v from jsonb_array_elements_text(coalesce(x.accepted, '[]'::jsonb)) with ordinality as e(v, n)
             order by e.n),
       coalesce(x.typable, true), 'published',
